class OriginalPreset {
  final String name, source;
  final int index;
  final bool partial;
  const OriginalPreset(this.name, this.source, this.index,
      {this.partial = false});
  Formation decode({String mapId = 'pool'}) => WebsiteCodec.decode(
      partial ? '${WebsiteCodec.mapIds.indexOf(mapId)},$source' : source);
}

